cd "e:/Desktop/Projects/ecomGliders" && node <<'EOF'
const fs = require('fs');
const path = require('path');
const dir = 'content/config/services';
for (const f of fs.readdirSync(dir).filter(x=>x.endsWith('.json')).sort()) {
  const d = JSON.parse(fs.readFileSync(path.join(dir,f),'utf8'));
  const mods = d.modules || [];
  const surviving = mods.filter(m => {
    if (m.type === 'processSteps') return false;
    if (m.type === 'checklistMatrix') return false;
    if (m.type === 'comparisonTable' && d.differ) return false;
    return true;
  });
  const assets = [];
  for (const m of surviving) {
    for (const img of (m.images||m.items||[])) {
      assets.push(`${m.type}:${img.src}`);
    }
    if (m.type === 'metricChart') assets.push(`metricChart:${m.points?.length||0}pts`);
  }
  console.log('\n'+d.slug);
  console.log('  H1:', d.hero.title);
  console.log('  rendered:', surviving.map(m=>m.type).join(', ')||'(none)');
  console.log('  assets:', assets.join(' | ')||'none');
}
EOF
